"use client";

import * as React from "react";
import { cn } from "@/lib/utils";
import { RadialChart } from "@/components/moneytrees/charts/radial-chart";
import { RollingNumber, usePrefersReducedMotion } from "@/components/moneytrees/charts/chart-engine";

type Props = {
  value: number; // -1..+1
  size?: "sm" | "md";
  showLabels?: boolean;
  className?: string;
};

function tone(value: number) {
  if (value > 0.15) return { label: "Bullish", color: "var(--spectrum-chart-up)" };
  if (value < -0.15) return { label: "Bearish", color: "var(--spectrum-chart-down)" };
  return { label: "Neutral", color: "var(--color-muted-foreground)" };
}

/** Semi-circle gauge: -1 (bearish) to +1 (bullish), the fill colour follows the tone. */
export function SentimentMeter({ value, size = "md", showLabels = true, className }: Props) {
  const reduce = usePrefersReducedMotion();
  const clamped = Math.max(-1, Math.min(1, value));
  const { label, color } = tone(clamped);
  const width = size === "sm" ? 120 : 176;
  const height = size === "sm" ? 76 : 108;

  return (
    <div
      className={cn("inline-flex flex-col items-center gap-1", className)}
      role="img"
      aria-label={`Sentiment ${label}, ${clamped.toFixed(2)}`}
    >
      <div style={{ width }}>
        <RadialChart
          variant="semi"
          data={[{ name: label, value: (clamped + 1) * 50, color }]}
          max={100}
          showLegend={false}
          height={height}
          className="h-auto"
          center={
            <div className="flex flex-col items-center leading-none">
              <span className="font-mono text-lg font-medium tabular-nums text-foreground">
                <RollingNumber
                  value={clamped}
                  format={(v) => `${v > 0 ? "+" : ""}${v.toFixed(2)}`}
                  animate={!reduce}
                />
              </span>
              <span
                className="mt-1 text-[10px] font-medium uppercase tracking-wide"
                style={{ color }}
              >
                {label}
              </span>
            </div>
          }
        />
      </div>
      {showLabels && (
        <div
          className="flex w-full justify-between text-[10px] text-muted-foreground"
          style={{ width }}
        >
          <span>Bearish</span>
          <span>Bullish</span>
        </div>
      )}
    </div>
  );
}
